create or replace function public.factory_claim_next_direct_run(p_worker_id text) returns jsonb language plpgsql security invoker set search_path='' as $$ declare v_run public.factory_runs%rowtype;v_task public.factory_tasks%rowtype;v_project public.factory_projects%rowtype;v_branch text;begin if nullif(btrim(p_worker_id),'') is null then raise exception 'worker_id is required';end if;select r.* into v_run from public.factory_runs r join public.factory_tasks t on t.id=r.task_id where r.status='queued' and r.execution_route='direct' and t.status='queued_execution' order by r.created_at for update of r skip locked limit 1;if v_run.id is null then return null;end if;select * into v_task from public.factory_tasks where id=v_run.task_id for update;select * into v_project from public.factory_projects where id=v_task.project_id;v_branch:='factory/task-'||v_task.id::text;update public.factory_runs set status='implementing',started_at=coalesce(started_at,now()),metadata=metadata||jsonb_build_object('execution_worker_id',p_worker_id,'execution_claimed_at',now()) where id=v_run.id;update public.factory_tasks set status='implementing',updated_at=now() where id=v_task.id;insert into public.factory_audit_events(project_id,task_id,run_id,actor_type,actor_ref,event_type,payload) values(v_project.id,v_task.id,v_run.id,'system',p_worker_id,'execution.direct.claimed','{}'::jsonb);return jsonb_build_object('run_id',v_run.id,'task_id',v_task.id,'project_key',v_project.project_key,'repository',v_project.repository,'issue_number',null,'title',v_task.title,'description',v_task.description,'branch',v_branch,'human_gate_required',coalesce((v_run.metadata->>'human_gate_required')::boolean,false));end;$$;
revoke all on function public.factory_claim_next_direct_run(text) from public,anon,authenticated;grant execute on function public.factory_claim_next_direct_run(text) to service_role;
